window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":160,"source":"خطبه 160.docx","mode":"explicit-parts","parts":["خطبه ۱۶۰\nبخش اول\nمتن:\nعظمة اللّه:\nأَمْرُهُ قَضَاءٌ وَ حِكْمَةٌ، وَ رِضَاهُ أَمَانٌ وَ رَحْمَةُ، يَقْضِي بِعِلْمٍ وَ يَعْفُو بِحِلْمٍ.\nحمد اللّه:\nاللَّهُمَّ لَكَ الْحَمْدُ عَلَى مَا تَأْخُذُ وَ تُعْطِي، وَ عَلَى مَا تُعَافِي وَ تَبْتَلِي، حَمْداً يَكُونُ أَرْضَى الْحَمْدِ لَكَ وَ أَحَبَّ الْحَمْدِ إِلَيْكَ وَ أَفْضَلَ الْحَمْدِ عِنْدَكَ، حَمْداً يَمْلَأُ مَا خَلَقْتَ وَ يَبْلُغُ مَا أَرَدْتَ، حَمْداً لَا يُحْجَبُ عَنْكَ وَ لَا يُقْصَرُ دُونَكَ، حَمْداً لَا يَنْقَطِعُ عَدَدُهُ وَ لَا يَفْنَى مَدَدُهُ.\nفَلَسْنَا نَعْلَمُ كُنْهَ عَظَمَتِكَ، إِلَّا أَنَّا نَعْلَمُ أَنَّكَ حَيٌّ قَيُّومُ، لَا تَأْخُذُكَ سِنَةٌ وَ لا نَوْمٌ؛ لَمْ يَنْتَهِ إِلَيْكَ نَظَرٌ وَ لَمْ يُدْرِكْكَ بَصَرٌ، أَدْرَكْتَ الْأَبْصَارَ وَ أَحْصَيْتَ الْأَعْمَالَ وَ أَخَذْتَ بِالنَّوَاصِي وَ الْأَقْدَامِ؛ وَ مَا الَّذِي نَرَى مِنْ خَلْقِكَ وَ نَعْجَبُ لَهُ مِنْ قُدْرَتِكَ وَ نَصِفُهُ مِنْ عَظِيمِ سُلْطَانِكَ، وَ مَا تَغَيَّبَ عَنَّا مِنْهُ وَ قَصُرَتْ أَبْصَارُنَا عَنْهُ وَ انْتَهَتْ عُقُولُنَا دُونَهُ وَ حَالَتْ سُتُورُ الْغُيُوبِ بَيْنَنَا وَ بَيْنَهُ أَعْظَمُ؛ فَمَنْ فَرَّغَ قَلْبَهُ وَ أَعْمَلَ فِكْرَهُ، لِيَعْلَمَ كَيْفَ أَقَمْتَ عَرْشَكَ وَ كَيْفَ ذَرَأْتَ خَلْقَكَ وَ كَيْفَ عَلَّقْتَ فِي الْهَوَاءِ سَمَاوَاتِكَ وَ كَيْفَ مَدَدْتَ عَلَى مَوْرِ الْمَاءِ أَرْضَكَ، رَجَعَ طَرْفُهُ حَسِيراً وَ عَقْلُهُ مَبْهُوراً وَ سَمْعُهُ وَالِهاً وَ فِكْرُهُ حَائِراً.\nترجمه:\nفرمان او قطعى و حکيمانه است و رضاى او امان و رحمت. با علم و آگاهى داورى مى کند و با حلم و بردبارى عفو مى نمايد.\nخداوندا سپاس و ستايش مخصوص توست، در برابر آن چه مى گيرى و آن چه عطا مى کنى و بر عافيت و بلايى که مى فرستى; حمد و سپاسى که رضايت بخش ترين حمدها نزد تو باشد; حمدى که محبوب ترين حمدها در پيشگاه توست; حمدى که برترين حمدها نزد تو خواهد بود. حمدى که تمام جهان خلقت را پر کند و تا آن جا که خواسته اى، برسد; حمدى که از تو محجوب و پوشيده نماند و در پيشگاه تو کاستى نداشته باشد; حمدى که عددش پايان نگيرد و در پهنه زمان، فنا در آن راه نيابد.\n(خداوندا) کنه عظمت تو را هرگز درک نمى کنيم، جز اين که مى دانيم تو زنده و قائم به ذات خود و ديگران قائم به تواند. هيچ گاه خواب سبک و سنگين، تو را فرا نمى گيرد (تا از بندگانت غافل شوى). افکار (بلندپرواز) هرگز به تو نمى رسد و چشم ها (ى تيزبين) تو را نمى بيند; ولى تو چشم ها (و حرکات آن ها) را مى بينى و اعمال و کردار (بندگان) را احصا مى کنى و زمام همگان به دست توست.\n(خداوندا) آن چه از مخلوقات را مشاهده مى کنيم و از قدرتت در شگفتى فرو مى رويم و وصف عظمت سلطنت تو را بيان مى کنيم، چه اهمّيّتى دارد؟! در حالى که آن چه از ما پوشيده و پنهان است و چشمانمان از ديدن آن قاصر و عقل ما در برابر درکشان ناتوان است و پرده هاى غيب ميان ما و آن ها فاصله افکنده، بس عظيم تر است.\n(آرى!) آن کس که قلبش را از همه چيز تهى کند و فکرش را به کار گيرد تا بداند چگونه عرش را برپا ساخته اى و مخلوقاتت را آفريده اى، چگونه کرات آسمان را در هوا معلق کرده اى، زمينت را بر روى امواج آب، گسترده اى، به يقين ديده فهمش وا مى ماند; عقلش مبهوت مى شود; شنوايى اش حيران، و انديشه اش سرگردان مى ماند!!\nتفسیر:\nرکن اساسی این خطبه، تبیین عظمت پروردگار است.\nامیرالمؤمنین صلوات‌الله‌علیه چهار ویژگی بنیادین را برای خداوند متعال برمی‌شمارند:\n🔷 «أَمْرُهُ قَضَاءٌ وَحِکمَةٌ»\nتمام فرمان‌های الهی (اعم از تکوینی و تشریعی) قطعی، حتمی و تردیدناپذیر است؛ و سراسر اوامر او بر پایه حکمت استوار گشته است.\n«إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَیئًا أَنْ یقُولَ لَهُ کنْ فَیکونُ»\nفرمان الهی یا تکوینی است؛ بدین معنا که به‌محض تعلق اراده‌اش، هستی می‌یابد:\n«ای آسمان پدید آی»، پس بی‌درنگ پدید می‌آید؛\n«ای خورشید در این مدار و بر اساس این قاعده گردش نما»، پس به گردش درمی‌آید. همه موجودات تحت تدبیر و اراده ربوبی اداره می‌شوند و هیچ گریزگاهی از فرمان الهی وجود ندارد.\nیا فرمان الهی، تشریعی است؛ مانند امر به بندگی و طاعت، و نهی از نافرمانی و معصیت؛ با این پیام که باید بدین شیوه سلوک نمایید.\nشبهه: اگر هر فرمانی از سوی خدا حتمی و لازم‌الاجرا باشد، آیا شبیه حاکمان مستبد و متکبر نخواهد شد که اصرار بر اجرای بی‌چون‌وچرا اوامر خویش دارند؟! تفاوت این دو در چیست؟!\nپاسخ: هنگامی که دیگران سخنشان مطاع می‌گردد - یعنی هر فرمانی صادر کنند شنیده شده و بی‌چون‌وچرا اطاعت می‌شود - به‌تدریج منشأ تباهی گشته و در معرض طغیان و استبداد قرار می‌گیرند.\nدومین عامل تباهی آدمی آن است که هرگاه خود را بی‌نیاز بپندارد (به‌ویژه بی‌نیازی مادی)، دست به سرکشی و طغیان می‌زند.\nاما فرمان خدا هرگز مردود و باطلشانی نیست؛ چرا که اوامر و احکام الهی برخاسته از حکمت بالغه است و نه از سرِ هواوهوس. حکمت پروردگار بر تمامی صفات و افعال او احاطه دارد؛\nصفاتی چون رحمانیت، رزاقی‌ات و منتقم بودن، همگی ذیل حکمت الهی معنا می‌یابند:\nاگر می‌بخشاید، بر اساس حکمت است؛\nو اگر کیفر می‌دهد و انتقام می‌گیرد، آن نیز بر پایه حکمت استوار است.\n🔷 «وَرِضَاهُ أَمَانٌ وَرَحْمَةٌ»\nخشنودی و رضایت الهی، پناهگاه و امانی در برابر عذاب و خشم خداست؛ و افزون بر آن، سراسر فیض و رحمت شمرده می‌شود. دستیابی به رضای الهی، جلب‌کننده رحمت بی‌پایان اوست.\n🔷 «یقْضِی بِعِلْمٍ»\nداوری و قضای الهی همراه با علم حضوری و آگاهی مطلق است؛ جهل و ناآگاهی در آن راهی ندارد تا نیازمند گواهیِ دروغ یا سوگند ناروا باشد. خداوند در قضاوت به هیچ گواهی تکیه نمی‌کند؛ بلکه علم بی‌انتهای اوست که اساس داوری قرار می‌گیرد.\n«مَا أَشْهَدْتُهُمْ خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ وَلَا خَلْقَ أَنْفُسِهِمْ» (کهف: ۵۱)\nپروردگار در آفرینش آسمان‌ها و زمین و نه در آفرینش نفوس آدمی، هیچ‌کس را به گواهی فرانخواند.\n🔷 «وَیعْفُو بِحِلْمٍ»\nبخشش و گذشت پروردگار همراه با حلم، بردباری و وقار است.\nاینکه خداوند کیفر گناهکاران را به تأخیر می‌اندازد، هرگز از روی بیم یا ناتوانی نیست؛ بلکه وجود حکیم در مجازات خطاکاران شتاب نمی‌ورزد. این درنگ و مهلت، خود بستری برای توبه و بازگشت بندگان فراهم می‌سازد.\nحلم الهی سرچشمه بخشایش و مغفرت است.\nخداوند مهلت می‌دهد؛ این مهلت و تأخیر برای گروهی زمینه‌ساز بازگشت و انابه است، و برای گروهی دیگر عذاب استدراج (فرورفتن تدریجی در گناه و هلاکت) به شمار می‌رود:\n«سَنَسْتَدْرِجُهُمْ مِنْ حَیثُ لَا یعْلَمُونَ * وَأُمْلِی لَهُمْ» (اعراف: ۱۸۲-۱۸۳)\nآنان را از جایی که درنمی‌یابند به‌تدریج گرفتار می‌سازیم و به ایشان مهلت می‌دهیم.\n🔷 «اللَّهُمَّ لَک الْحَمْدُ عَلَی مَا تَأْخُذُ وَتُعْطِی»\nبار خدایا، ستایش ویژه توست بر آنچه بازمی‌ستانی [تَأْخُذُ] و بر آنچه ارزانی می‌داری [تُعْطِی].\n🔷 «وَعَلَی مَا تُعَافِی وَتَبْتَلِی»\nو تو را سپاس می‌گوییم بر تندرستی و عافیتی که بخشیده‌ای، و بر ابتلائات، نیازمندی‌ها، بیماری‌ها و ناملایماتی که مقدر فرموده‌ای شکر می‌گزاریم؛ چرا که تمامی مقدرات الهی هدفمند بوده و بر اساس مصلحت و تدبیر دقیق استوار است.\nقرآن کریم انسان‌ها را در مواجهه با فراوانی و کاستی به دو گروه تقسیم می‌کند:\n«فَأَمَّا الْإِنْسَانُ إِذَا مَا ابْتَلَاهُ رَبُّهُ فَأَکرَمَهُ وَنَعَّمَهُ فَیقُولُ رَبِّی أَکرَمَنِ»\nهنگامی که پروردگارش او را با فراخی نعمت بیازماید و گرامی‌اش دارد، مغرورانه می‌گوید: پروردگارم مرا گرامی داشته است؛\nاما همین انسان چون با تنگنا روبه‌رو گردد:\n«وَأَمَّا إِذَا مَا ابْتَلَاهُ فَقَدَرَ عَلَیهِ رِزْقَهُ فَیقُولُ رَبِّی أَهَانَنِ» (فجر: ۱۵-۱۶)\nچون روزی‌اش تنگ شود، لب به گلایه گشوده و می‌گوید: پروردگارم مرا خوار ساخته است!\nحال‌آنکه همگان در بوته آزمایش الهی قرار دارند؛ و هرگز ثروت و عطایا نشانه کرامت ذاتی نبوده و تنگدستی و محرومیت‌ها نشانه خواری و تحقیر به شمار نمی‌آید.\n🔷 «حَمْدًا یکونُ أَرْضَی الْحَمْدِ لَک»\nتو را ستایش می‌گوییم؛ ستایشی که خشنودکننده‌ترین سپاس در پیشگاه والای تو باشد.\n🔷 «وَأَحَبَّ الْحَمْدِ إِلَیک، وَأَفْضَلَ الْحَمْدِ عِنْدَک»\nو ستایشی که محبوب‌ترین سپاس نزد تو و برترین نمونه حمد در پیشگاه قدس تو به شمار آید.\nمحبوب‌ترین و والاترین مرتبه سپاسگزاری در هر دو حال (هنگام برخورداری از نعمت و هنگام سلب آن) تجلی می‌یابد.\n🔷 «حَمْدًا یمْلَأُ مَا خَلَقْتَ، وَیبْلُغُ مَا أَرَدْتَ»\nتو را سپاس می‌گویم؛ ستایشی چنان فراگیر که گستره آفرینش و سراسر جهان را آکنده سازد [یمْلَأُ] و عالم ندای این شکرگزاری را بشنود؛ و حمد من به همان جایگاهی واصل گردد که تو اراده فرموده‌ای.\nمعنای دوم: تو را در قبال تمامی آفریدگان ستایش می‌کنیم؛ چرا که هستی همگی در مسیر منافع ما جریان دارد. چنان سپاس می‌گوییم که همه موجودات را در بر گیرد؛ از جمله آفرینش شیطان که خود بستری برای رشد معنوی و برترین میدان جهاد و مبارزه است، و بر وجود چنین آزمونی نیز شکر می‌گزاریم.\n🔷 «حَمْدًا لَا یحْجَبُ عَنْک»\nتو را سپاس می‌گویم؛ ستایشی که هیچ مانعی در برابرش نباشد و از حریم قرب خدا پوشیده نماند؛ حمدی که حجابی بر آن نیفتد تا مانع وصول به پیشگاه الهی گردد. چرا که ستایش آلوده به بوی حسادت یا حمدی که باهدف بر زمین‌زدن دیگران ادا شود، هرگز به درگاه حق‌تعالی بار نخواهد یافت.\n🔷 «وَلَا یقْصَرُ دُونَک»\nو ستایشی که از رسیدن به بارگاه قدس تو بازنماند و کوتاه نیاید.\n🔷 «حَمْدًا لَا ینْقَطِعُ عَدَدُهُ»\nحمدی که شمارش آن هرگز پایان نپذیرد و پیوسته و پایدار بماند.\nحضرت فرمودند: حمد نباید محدود و محصور گردد؛\nشمارش حمد نشان می‌دهد که اگر ذکر، صرفاً زبانی باشد، پایان‌پذیر خواهد بود؛ زیرا با فرارسیدن خواب، ذکر زبان خاموش می‌گردد؛\nدرحالی‌که بیان فرموده‌اند عدد آن نباید دستخوش انقطاع شود.\nاین حمد، سپاسگزاریِ عملی و مرتبه‌ای است که سراسر تاروپود وجود آدمی باید شاکر باشد. کاستی‌ها و ابتلائات زندگی شایسته سپاس است، آن هم سپاسی وجودی تا هیچ‌گونه گسستی در آن راه نیابد.\n🔷 «وَلَا یفْنَی مَدَدُهُ»\nتو را سپاس می‌گویم؛ ستایشی که امتداد، اثر و مدد بخشیِ آن هرگز دستخوش زوال و فنا نگردد. شکرگزاری دارای اثری عینی است؛ نیروی امدادیِ نیرومندی است که عنایت الهی را به یاری انسان فرامی‌خواند؛\nحمدی که همراهی و نصرت بخشیِ آن پایانی نداشته باشد.\nهرگاه حمد تو به ساحت ربوبی واصل گردد،\nدر سختی‌ها و بحران‌ها به‌سوی خودت بازمی‌گردد و دستگیرت می‌شود؛ شکرگزاریِ گذشته تو، امنیت و تعالی آینده‌ات را تضمین می‌نماید و همواره مدد بخش خواهد بود.\n🔷 «فَلَسْنَا نَعْلَمُ کنْهَ عَظَمَتِک، إِلَّا أَنَّا نَعْلَمُ أَنَّک حَی قَیومٌ، لَا تَأْخُذُک سِنَةٌ وَلَا نَوْمٌ»\nما ژرفای عظمت بی‌انتهای تو را درنمی‌یابیم، جز آنکه با تمام وجود آگاهیم که تو زنده‌ای پاینده و برپادارنده هستی، هستی [حَی قَیومٌ]؛ نه هیچ چرت و خواب سبکی تو را فرامی‌گیرد و نه خوابی گران.\nخدایا، هرچند شکرگزاری در خورِ عظمت بی‌انتهای تو خارج از توان و طاقت محدود ماست،\nو هرگز به کنه ذات بی‌پایانت راهی نداریم، اما درگاه معرفت و شناخت تو به روی ما مسدود نیست.\nتنها حقیقتی که بدان معرفت داریم این است که تو زنده جاوید و برپادارنده وجودی؛ همه عالمیان و تمامی موجودات به فیض تو وابسته‌اند و تنها تو هستی که قائم به ذات خویشی.\nموجود زنده امکانی پیوسته درحال‌رشد و تکامل است، اما ساحت ربوبی از این مفاهیم مبراست. در مباحث کلامی، حیات الهی به علم و قدرت مطلق او تفسیر می‌شود؛ یعنی ازآنجاکه خداوند دارای علم و قدرت بی‌پایان است، پس زنده حقیقی است و برای حیات ذات الهی نیاز به دلایل ثانویه نیست.\nاینکه در قرآن کریم تصریح شده شهیدان زنده‌اند، از همین زاویه است؛ زیرا شهیدان حقیقت را می‌دانند و توان تصرف دارند.\nحیات شهید بدین معناست که به هنگام توسل، از گرفتاری فرد آگاه است و توانایی گره‌گشایی را نیز داراست و مشکل را برطرف می‌سازد؛ حیات حقیقی شهید به خوردن و آشامیدن و زادوولد نبوده، بلکه به تجلیِ علم و قدرت اوست.\n🔷 «لَمْ ینْتَهِ إِلَیک نَظَرٌ، وَلَمْ یدْرِکک بَصَرٌ»\nهیچ اندیشه و نگاه فکریِ بشری [نَظَرٌ] به قله عظمت پروردگار دست نمی‌یابد و هیچ خردی توان احاطه بر او را ندارد؛ هیچ دیده‌ای نیز توان مشاهده ذات الهی را ندارد [لَمْ یدْرِکک]، چرا که او جسم نیست؛ و ازآنجاکه خداوند آفریدگار عقل و تفکر است، اندیشه آفریده محدودتر از احاطه بر خالق خواهد بود.\n🔷 «أَدْرَکتَ الْأَبْصَارَ، وَأَحْصَیتَ الْأَعْمَالَ، وَأَخَذْتَ بِالنَّوَاصِی وَالْأَقْدَامِ»\nخدایا، تو همه دیدگان را درمی‌یابی؛ چشم خیانت‌پیشه و نگاه رحمت نگر را می‌بینی، غایت هر نگاهی را می‌دانی و تمامی اعمال بندگان را با دقتی موشکافانه شمارش و محاسبه می‌کنی.\nبا فرا چنگ گرفتن موی پیشانی‌ها [نَوَاصِی] و گام‌ها، انسان سراسر مهار گشته و در پهنه قدرت و تسخیر الهی قرار می‌گیرد.\n🔷 «وَمَا الَّذِی نَرَی مِنْ خَلْقِک، وَنَعْجَبُ لَهُ مِنْ قُدْرَتِک»\nبار الها، آنچه از پهنه آفرینشت مشاهده می‌کنیم و پیش چشم ما قرار داده‌ای [نَرَی]، و ما را از عظمت و ظرافت قدرتت به شگفتی و تحیر واداشته است [نَعْجَبُ]، در برابر عظمتی که بر ما پوشیده مانده بسیار ناچیز است.\n🔷 «وَنَصِفُهُ مِنْ عَظِیمِ سُلْطَانِک، وَمَا تَغَیبَ عَنَّا مِنْهُ»\nآنچه از شکوه و عظمت سلطنتت توصیف می‌کنیم، در برابر آن حقایق غیبی، عوالم ماورای، عرش و جبروتی که از دیدگان ما پنهان گشته، اندک و ناچیز است.\nآنچه از شگفتی‌ها و عظمت آفرینش به ما نمایانده‌ای، در قیاس با آنچه نمی‌بینیم هیچ به شمار می‌آید.\nیکی از آن عوالم پنهان، بهشت جاویدان است که در توصیف آن فرمود:\n«عَلَی سُرُرٍ مَوْضُونَةٍ * مُتَّکئِینَ عَلَیهَا مُتَقَابِلِینَ» (واقعه: ۱۵-۱۶)\nبهشتیان بر تخت‌های بافته‌شده از گوهر تکیه زده‌اند و روبه‌روی یکدیگر قرار دارند. ما در این عالم ماده توان مشاهده هم‌زمان چند نفر را پیشرو داریم؟ ده یا بیست نفر!\nاما در سرای بهشت، هر فرد هم‌زمان در برابر تمامی بهشتیان قرار می‌گیرد.\nمی‌فرماید: این حقیقت، تنها جلوه‌ای از عوالم غیب و اسرار پوشیده است؛ چگونه خرد مادی می‌تواند آن را دریابد؟!\nاین عوالم غیبی بسی فراتر از مشاهدات محدود ماست؛ خرد در برابر آن به شگفتی می‌افتد و تنها ذات واجب‌الوجود از کنه حقایق آگاه است.\n🔷 «وَقَصُرَتْ أَبْصَارُنَا عَنْهُ»\nدرحالی‌که دیدگان مادی ما از مشاهده آن عوالم پنهان و غیبی ناتوان و فرومانده است.\n🔷 «وَانْتَهَتْ عُقُولُنَا دُونَهُ»\nو نه‌تنها دیدگان مادی، بلکه اندیشه‌ها و عقول بشری نیز پیش از رسیدن به آن حقیقت متوقف شده و محدودتر از آن است که خرد توان درک و احاطه بر حقایق عرش، کرسی و آسمان‌ها را داشته باشد.\n🔷 «وَحَالَتْ سُتُورُ الْغُیوبِ بَینَنَا وَبَینَهُ أَعْظَمُ»\nبار خدایا، تو چنان مقدر فرموده‌ای که میان ما و آن حقایق برتر، پرده‌های غیب فاصله اندازد [حَالَتْ] تا بسیاری از امور پنهان بماند.\nنه ما آن عوالم را مشاهده می‌کنیم و نه خداوند رخصت مشاهده داده است؛ و همه این نشانه‌ها گواه ضعف و ناتوانی انسان در برابر عظمت پروردگار است.\nحضرت فرمودند: مرا از دانش غیب بهره‌ای است که اگر با شما در میان نهم، سراپای‌تان را اضطراب و هراس فرامی‌گیرد.\n🔷 «فَمَنْ فَرَغَ قَلْبُهُ، وَأَعْمَلَ فِکرَهُ»\nپس هرآن‌کس که دل خویش را از مشغله‌های دنیوی فارغ سازد و گوهر تفکر خود را به کار گیرد تا دریابد:\n🔷 «لِیعْلَمَ کیفَ أَقَمْتَ عَرْشَک»\nالف) تا بداند عرش با عظمتت را چگونه برپا داشته‌ای؛\n🔷 «وَکیفَ ذَرَأْتَ خَلْقَک»\nب) و چگونه مخلوقات گوناگون را پدید آورده‌ای [ذَرَأْتَ]؛\nهزاران گونه از موجودات با ساختارهای متمایز، کارکردهای ویژه، ابزارها و سازمان وجودی خاص، و با سازوکارهای ویژه معیشتی چگونه خلقت یافته‌اند؛\n🔷 «وَکیفَ عَلَّقْتَ فِی الْهَوَاءِ سَمَاوَاتِک»\nج) و چگونه آسمان‌ها را در پهنه فضا معلق و برافراشته ساخته‌ای؛\nخورشیدی که با جرم و سنگینیِ بی‌شمارش در قیاس با برخی کرات کهکشانی همچون دانه‌ای کوچک می‌نماید، چگونه بر مداری دقیق و تنظیم‌شده در گردش است؛\n🔷 «وَکیفَ مَدَدْتَ عَلَی مَوْرِ الْمَاءِ أَرْضَک»\nد) و چگونه زمین را بر پهنه امواج خروشان آب گسترش بخشیده‌ای؛ چگونه خشکی‌ها پدیدار گشته و آب‌ها مهار شده‌اند؟\nچگونه با یکدیگر تداخل ویرانگر پیدا نمی‌کنند؟\nو چگونه خاک‌ها در مجاورت بستر فراگیر آب، رطوبت زده و ناپایدار نمی‌شوند و درعین‌حال سخت و استوار پابرجا مانده‌اند؟\n🔷 «رَجَعَ طَرْفُهُ حَسِیرًا، وَعَقْلُهُ مَبْهُورًا»\nسرانجامِ تمام این اندیشه‌ورزی‌ها آن است که نگاه خیره [طَرْفُهُ] خسته، فرومانده و ناتوان [حَسِیرًا] بازمی‌گردد،\nو خرد آدمی مبهوت، سرگشته و حیران می‌ماند.\n🔷 «وَسَمْعُهُ وَالِهًا، وَفِکرُهُ حَائِرًا»\nو گوش در برابر این شکوه واله و شیدا می‌گردد و اندیشه، سرگردان [حَائِرًا] و فرومانده بر جای می‌ماند.\nپس پروردگار را سپاس گویید و بدانید که حمد و ستایش شما در برابر عظمت بی‌پایان خدا ذره‌ای به‌حساب نمی‌آید.\n«اللَّهُمَّ حَقِّقْنَا بِحَقَائِقِ الْأُمُورِ»","بخش دوم\nمتن:\nكيف يكون الرجاء:\nيَدَّعِي بِزَعْمِهِ أَنَّهُ يَرْجُو اللَّهَ، كَذَبَ وَ الْعَظِيمِ، مَا بَالُهُ لَا يَتَبَيَّنُ رَجَاؤُهُ فِي عَمَلِهِ، فَكُلُّ مَنْ رَجَا عُرِفَ رَجَاؤُهُ فِي عَمَلِهِ، وَ كُلُ رَجَاءٍ إِلَّا رَجَاءَ اللَّهِ تَعَالَى فَإِنَّهُ مَدْخُولٌ، وَ كُلُّ خَوْفٍ مُحَقَّقٌ إِلَّا خَوْفَ اللَّهِ فَإِنَّهُ مَعْلُولٌ، يَرْجُو اللَّهَ فِي الْكَبِيرِ وَ يَرْجُو الْعِبَادَ فِي الصَّغِيرِ، فَيُعْطِي الْعَبْدَ مَا لَا يُعْطِي الرَّبَّ؛ فَمَا بَالُ اللَّهِ جَلَّ ثَنَاؤُهُ يُقَصَّرُ بِهِ عَمَّا يُصْنَعُ بِهِ لِعِبَادِهِ، أَ تَخَافُ أَنْ تَكُونَ فِي رَجَائِكَ لَهُ كَاذِباً، أَوْ تَكُونَ لَا تَرَاهُ لِلرَّجَاءِ مَوْضِعاً؟ وَ كَذَلِكَ إِنْ هُوَ خَافَ عَبْداً مِنْ عَبِيدِهِ أَعْطَاهُ مِنْ خَوْفِهِ مَا لَا يُعْطِي رَبَّهُ، فَجَعَلَ خَوْفَهُ مِنَ الْعِبَادِ نَقْداً، وَ خَوْفَهُ مِنْ خَالِقِهِ ضِمَاراً وَ وَعْداً؛ وَ كَذَلِكَ مَنْ عَظُمَتِ الدُّنْيَا فِي عَيْنِهِ وَ كَبُرَ مَوْقِعُهَا مِنْ قَلْبِهِ آثَرَهَا عَلَى اللَّهِ تَعَالَى، فَانْقَطَعَ إِلَيْهَا وَ صَارَ عَبْداً لَهَا.\nرسول اللّه (صلی الله علیه وآله):\nوَ لَقَدْ كَانَ فِي رَسُولِ اللَّهِ كَافٍ لَكَ فِي الْأُسْوَةِ، وَ دَلِيلٌ لَكَ عَلَى ذَمِّ الدُّنْيَا وَ عَيْبِهَا وَ كَثْرَةِ مَخَازِيهَا وَ مَسَاوِيهَا، إِذْ قُبِضَتْ عَنْهُ أَطْرَافُهَا وَ وُطِّئَتْ لِغَيْرِهِ أَكْنَافُهَا وَ فُطِمَ عَنْ رَضَاعِهَا وَ زُوِيَ عَنْ زَخَارِفِهَا.\nموسى (علیه السلام):\nوَ إِنْ شِئْتَ ثَنَّيْتُ بِمُوسَى كَلِيمِ اللَّهِ، حَيْثُ يَقُولُ «رَبِّ إِنِّي لِما أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ»، وَ اللَّهِ مَا سَأَلَهُ إِلَّا خُبْزاً يَأْكُلُهُ، لِأَنَّهُ كَانَ يَأْكُلُ بَقْلَةَ الْأَرْضِ وَ لَقَدْ كَانَتْ خُضْرَةُ الْبَقْلِ، تُرَى مِنْ شَفِيفِ صِفَاقِ بَطْنِهِ لِهُزَالِهِ وَ تَشَذُّبِ لَحْمِهِ.\nداود (علیه السلام):\nوَ إِنْ شِئْتَ ثَلَّثْتُ بِدَاوُدَ صَاحِبِ الْمَزَامِيرِ وَ قَارِئِ أَهْلِ الْجَنَّةِ، فَلَقَدْ كَانَ يَعْمَلُ سَفَائِفَ الْخُوصِ بِيَدِهِ وَ يَقُولُ لِجُلَسَائِهِ أَيُّكُمْ يَكْفِينِي بَيْعَهَا، وَ يَأْكُلُ قُرْصَ الشَّعِيرِ مِنْ ثَمَنِهَا.\nعيسى (علیه السلام):\nوَ إِنْ شِئْتَ قُلْتُ فِي عِيسَى ابْنِ مَرْيَمَ، فَلَقَدْ كَانَ يَتَوَسَّدُ الْحَجَرَ وَ يَلْبَسُ الْخَشِنَ وَ يَأْكُلُ الْجَشِبَ، وَ كَانَ إِدَامُهُ الْجُوعَ وَ سِرَاجُهُ بِاللَّيْلِ الْقَمَرَ وَ ظِلَالُهُ فِي الشِّتَاءِ مَشَارِقَ الْأَرْضِ وَ مَغَارِبَهَا وَ فَاكِهَتُهُ وَ رَيْحَانُهُ مَا تُنْبِتُ الْأَرْضُ لِلْبَهَائِمِ، وَ لَمْ تَكُنْ لَهُ زَوْجَةٌ تَفْتِنُهُ وَ لَا وَلَدٌ يَحْزُنُهُ وَ لَا مَالٌ يَلْفِتُهُ وَ لَا طَمَعٌ يُذِلُّهُ، دَابَّتُهُ رِجْلَاهُ وَ خَادِمُهُ يَدَاهُ.\nترجمه:\nاو گمان مى برد، به خدا اميدوار است; اما سوگند به خدا دروغ مى گويد (اگر راست مى گويد) چرا اين اميدوارى در عملش ديده نمى شود؟ زيرا هر کس به چيزى اميد دارد، در عملش مشاهده مى شود (همه بايد بدانند) هر اميدى جز اميد به خداى متعال نابجا، و هر ترس جز ترس از (مخالفت با) خدا نادرست است.\n(اين مدعى دروغين) در مسائل مهم به خدا اميد دارد و در مسائل کوچک به بندگان خدا; در حالى که تواضع و احترامش در برابر بندگان (براى همان مسائل کوچک) بيش از خداست. چه شده است که تواضع واحترام او براى خداوند متعال کم تر از بندگان است؟ آيا مى ترسى در اظهار اميد به خدا دروغگو باشى؟ يا او را شايسته اميد نمى دانى؟ (که اين هر دو خيالى است باطل) همچنين اگر او از يکى از بندگان خدا بترسد به سبب اين خوف، براى او اهمّيّتى قائل مى شود که براى خدا قائل نيست; در واقع خوف از بندگان را نقد مى شمرد و خوف از پروردگار خويش را وعده اى دور از انتظار! (آرى) کسى که دنيا در چشم او بزرگ جلوه کند و جايگاه آن در قلبش مهم باشد، آن را بر خداى متعال مقدّم مى دارد. از همه چيز مى بُرَد و به دنيا مى پيوندد و برده آن مى شود.\nبراى تو (اى دلباخته دنيا) کافى است که روش رسول خدا(صلى الله عليه وآله) را سرمشق خود قرار دهى و دليل و راهنماى خود در نکوهش دنيا و مذمت آن و رسوايى فراوان و بدى هايش بشمارى; چه اين که مواهب دنيا از او گرفته شد و براى ديگران آماده گشت. او از پستان دنيا جدا و از زخارف و زيبايى هايش برکنار شده بود.\nاگر بخواهى دوّمين نفر يعنى موساى کليم(عليه السلام) به تو معرفى مى کنم، آن گاه که عرضه داشت: پروردگارا! به آن چه به من از نيکى عطا کنى نيازمندم، به خدا سوگند! موسى(عليه السلام) غير از قرص نانى که بخورد از خدا نخواست; زيرا وى (از زمانى که از مصر فرار کرد و به سوى مدين آمد) از گياهان زمين تغذيه مى کرد تا آن جا که بر اثر لاغرى شديد و تحليل رفتن گوشت بدن او رنگ سبز گياه از پشت پرده شکمش آشکار بود.\nو چنان چه بخواهى سوّمين نفر داوود ـ که درود خدا بر او باد ـ صاحب «مزامير» و قارى بهشتيان را به تو معرفى مى کنم; او با دست خويش از برگ درخت خرما زنبيل مى بافت و به دوستانش مى گفت کدام يک از شما حاضر است اين ها را براى من بفروشد، از بهاى آن قرص نان جويى تهيه مى کرد و تناول مى نمود.\nو اگر بخواهى (نمونه ديگرى از) زندگى عيسى بن مريم ـ که درود خدا بر او باد ـ را برايت بازگو مى کنم; او سنگ را بالش خود قرار مى داد; لباس خشن مى پوشيد; غذاى ناگوار مى خورد; نان خورش او گرسنگى، چراغ شب هايش ماه، سر پناه او در زمستان مشرق و مغرب زمين بود (صبح ها در طرف غرب و عصرها در طرف شرق رو به آفتاب قرار مى گرفت) ميوه و گل او گياهانى بود که از زمين براى چهارپايان مى رويد; نه همسرى داشت که او را بفريبد و نه فرزندى که (مشکلاتش) او را غمگين سازد; نه مالى داشت که او را به خود مشغول دارد و نه طمعى که خوارش کند; مرکبش پاهايش بود و خادمش دست هايش!\nتفسیر:\n در بخش ابتدایی، حضرت درباره حکمت الهی بیان می‌فرمایند که هر امری که از سوی خداوند صادر می‌شود، هدفمند است؛ البته هدف، رشد خداوند نیست، زیرا او کمال مطلق است، بلکه غرض، رشد انسان است.\n🔷 «یدَّعِی بِزَعْمِهِ أَنَّهُ یرْجُو اللَّهَ»\nانسان به گمان و ادعای خود می‌گوید که به خداوند امیدوار است.\nاین بخش به موضوع خوف‌ورجا مربوط می‌شود؛ یعنی فردی ادعا می‌کند که به خدا امید دارد.\n🔷 «کذَبَ وَالْعَظِیمِ»\nسوگند به خدای بزرگ که دروغ می‌گوید؛ چنین نیست که رجا تنها ادعایی زبانی باشد.\n🔷 «مَا بَالُهُ لَا یتَبَینُ رَجَاؤُهُ فِی عَمَلِهِ؟»\nاین شخص را چه شده است؟ چرا امیدواری او در عملش آشکار نیست؟ هنگامی که ادعای امیدواری می‌کند، باید نشانه‌ای از آن در رفتارش دیده شود.\n🔷 «فَکلُّ مَنْ رَجَا عَرَفَ رَجَاؤُهُ فِی عَمَلِهِ إِلَّا رَجَاءَ اللَّهِ تَعَالَی فَإِنَّهُ مَدْخُولٌ»\nهرکس ادعای امیدواری دارد، باید امیدش در عمل آشکار باشد. چنان‌که قرآن کریم می‌فرماید:\n«فَمَنْ کانَ یرْجُو لِقَاءَ رَبِّهِ فَلْیعْمَلْ عَمَلًا صَالِحًا» (کهف)\nهرکس به دیدار پروردگارش امید دارد، باید عمل صالح انجام دهد. ادعا کافی نیست؛ دلیل این ادعا چیست؟ امید به خدا باید در عمل آشکار باشد، اما ما در رفتار خود نشانه‌ای از این امیدواری نمی‌بینیم.\nتعبیر حضرت این است که اگر واقعاً در پی رسیدن به رجا و امید هستید، باید نشانه‌ای از آن وجود داشته باشد. در کتاب کافی، جلد دوم، صفحه ۶۸، در باب خوف‌ورجا آمده است:\n«قُلْتُ لَهُ قَوْمٌ یعْمَلُونَ بِالْمَعَاصِی وَیقُولُونَ نَرْجُو»\nبه امام معصوم عرض می‌کنند: گروهی مرتکب گناه می‌شوند و می‌گویند ما به خدا امیدواریم.\nآنان از ادعا دست برنمی‌دارند تا اینکه مرگشان فرامی‌رسد. امام می‌فرمایند: آنان قومی هستند که ادعای رجا دارند، اما در پی امیدی واهی‌اند. انسان اگر واقعاً امیدوار باشد، عمل صالح انجام می‌دهد. چنین نیست که اهل‌بیت علیهم‌السلام سپر و پوششی برای گناهان ما باشند؛ ما پیوسته گناه کنیم و پیوسته درخواست بخشش داشته باشیم.\nاثر ذاتی توسل و اشک ریختن بر اهل‌بیت علیهم‌السلام، پاک‌شدن گناهان است؛ اما ازسوی‌دیگر، نباید پیوسته گناه کنیم و انتظار داشته باشیم امام حسین علیه‌السلام ما را ببخشد. این امیدواری نیست، بلکه امیدی واهی است.\nاگر انسان از چیزی بترسد، از آن می‌گریزد. پس چگونه است که از گناه می‌ترسیم، اما از آن دوری نمی‌کنیم و عملی را که مورد رضایت خداوند باشد انجام نمی‌دهیم؟\n🔷 «فَکلُّ مَنْ رَجَا عَرَفَ رَجَاؤُهُ فِی عَمَلِهِ إِلَّا رَجَاءَ اللَّهِ تَعَالَی فَإِنَّهُ مَدْخُولٌ»\nهرکس ادعای امید به خدا دارد، باید امیدواری‌اش در عمل آشکار شود. هر امیدی جز امید به خدا، نابجا و [مَدْخُولٌ] نادرست است. امیدبستن به هرکس جز خدا، امیدی باطل و خطرآلود است.\nآنکه قدرت و علم کامل دارد، خداوند است و خود او نیز خویشتن را چنین معرفی کرده است. توسل‌جستن به چهارده نور مقدس برای گشایش کار، با امید داشتن به خدا منافاتی ندارد؛ اما امید اصلی باید به خداوند باشد. امیدبستن به هر چیزی جز خدا - خواه خود، علم، قدرت یا جوانی - آدمی را به بیراهه می‌کشاند.\n🔷 «وَکلُّ خَوْفٍ مُحَقَّقٍ إِلَّا خَوْفَ اللَّهِ فَإِنَّهُ مَعْلُولٌ»\nهر ترسی که به مرحله تحقق برسد، جز ترس از خداوند، بیمار و [مَعْلُولٌ] نادرست است. امیدبستن به غیر خدا، امیدی مردود و واهی است و ترسیدن از هرکس جز خدا نیز ترسی بی‌اساس به شمار می‌رود.\nدر مباحث دشمن‌شناسی، اهل‌بیت علیهم‌السلام می‌فرمایند دشمن را بشناسید، توانایی‌هایش را برآورد کنید و برنامه‌هایش را مهندسی معکوس نمایید؛ اما از دشمن نترسید. حضرت می‌فرمایند ترس از هرکس جز خداوند، نادرست است.\nآرامش در توحید و تکیه بر خداست. امام صادق علیه‌السلام فرمودند: فتنه‌ها را طلب کنید و از آن‌ها نترسید؛ زیرا در فتنه، شهادت، جانبازی و گرفتاری وجود دارد، اما همه این امور می‌تواند خیر و رحمت الهی باشد.\nحضرت در حکمت ۸۹ پنج توصیه بیان می‌فرمایند و می‌گویند اگر روزهای طولانی، بی‌وقفه حرکت کنید و سختی بکشید، برای دستیابی به این پنج اصل ارزش دارد:\n«لَا یرْجُونَّ أَحَدٌ مِنْکمْ إِلَّا رَبَّهُ»\nهیچ‌یک از شما جز به پروردگارش امید نبندد.\n«وَلَا یخَافَنَّ إِلَّا ذَنْبَهُ»\nو از هیچ‌کس جز گناه خود نترسد؛ از گناه خویش بیمناک باشد.\n🔷 «یرْجُو اللَّهَ فِی الْکبِیرِ وَیرْجُو الْعِبَادَ فِی الصَّغِیرِ»\nبرخی راه را اشتباه می‌روند؛ به‌جای آنکه در امور کوچک و بزرگ به خدا امید داشته باشند، به دیگران دل می‌بندند.\nحضرت در این تذکر می‌فرمایند که آنان به خدا امید دارند، اما امیدشان کامل و تمام نیست؛ در برخی امور به خدا امیدوارند و در برخی امور دیگر، به پدر، رئیس یا مردم توجه دارند.\nبرخی افراد در امور بزرگ، مانند رهایی از جهنم یا رسیدن به بهشت، به خدا امید دارند؛ در گرفتاری‌ها نیز به خدا پناه می‌برند، اما در امور کوچک به مردم، پول‌توجیبی یا دوستان خود امید می‌بندند. این نیز امیدبستن به غیر خداست.\n🔷 «فَیعْطِی الْعَبْدَ مَا لَا یعْطِی الرَّبَّ»\nدر برابر بندگان فروتنی می‌کند [یعْطِی]؛ به‌گونه‌ای که در برابر خداوند تواضع و فروتنی ندارد. در کاری کوچک، در برابر مردم چنان خضوع می‌کند که در برابر همه نعمت‌های الهی چنین تواضعی نشان نمی‌دهد.\nنخست آنکه این رفتار، نوعی شرک است؛ زیرا امید به غیر خدا بسته شده است. دوم آنکه فرد در برابر مخلوقات، بیش از خداوند فروتنی می‌کند.\n🔷 «فَمَا بَالُ اللَّهِ جَلَّ ثَنَاؤُهُ یقَصَّرُ بِهِ عَمَّا یصْنَعُ بِهِ لِعِبَادِهِ»\nچگونه است که حق خداوند کمتر از حق بندگان رعایت می‌شود؟ چرا در حق خدا کوتاهی می‌کنیم، اما در حق مردم کوتاهی نمی‌کنیم؟ چه شده است که خدا را چنان کوچک می‌شماریم که حاضر نیستیم در برابر او فروتنی کنیم و وظیفه خود را انجام دهیم؟\n🔷 «أَتَخَافُ أَنْ تَکونَ فِی رَجَائِک لَهُ کاذِبًا؟»\nآیا می‌ترسید امیدواری شما نسبت به خدا دروغ باشد؟ این جمله دو معنا دارد:\nنخست اینکه آیا می‌ترسید خداوند امید شما را دروغ بشمارد و دست رد به سینه‌تان بزند؟\nمعنای دوم این است که شاید خدا را رحمان و رحیم نمی‌دانید. این، مشکلی اعتقادی است؛ شاید خدا را تنها منتقم بدانید. درهرصورت، این اندیشه نادرست است. باید به خدا امید داشت و در برابر الطاف او فروتن بود.\n🔷 «أَوْ تَکونَ لَا تَرَاهُ لِلرَّجَاءِ مَوْضِعًا؟»\nیا خداوند را شایسته امیدواری نمی‌دانید و تصور می‌کنید او صلاحیت آن را ندارد که به او امید بسته شود؟ حال‌آنکه قدرت، علم و رحمت، همگی در اختیار اوست و باید حاجت خود را از او بخواهیم.\n🔷 «وَکذَلِک إِنْ هُوَ خَافَ عَبْدًا مِنْ عَبِیدِهِ أَعْطَاهُ مِنْ خَوْفِهِ مَا لَا یعْطِی رَبَّهُ»\nدر باب خوف نیز چنین است: اگر کسی از یکی از بندگان خدا بترسد، چنان در برابر او خضوع و کرنش می‌کند که هرگز در برابر خداوند چنین تواضعی نداشته است. چه بسیارند کسانی که از مردم می‌ترسند و در برابر حق کوتاه می‌آیند؛ درحالی‌که این ترس از خداوند نیست؛ خدایی که می‌تواند در همان لحظه مال و جان انسان را بگیرد و او را به دوزخ ببرد.\n🔷 «فَجَعَلَ خَوْفَهُ مِنَ الْعِبَادِ نَقْدًا، وَخَوْفَهُ مِنْ خَالِقِهِ ضِمَارًا وَوَعْدًا»\nزیرا ترس از مردم برای او نقد و حاضر است؛ می‌ترسد که مردم همین اکنون از او انتقام بگیرند؛ اما ترس از خداوند را مانند مالی نسیه می‌پندارد که هرگز امید وصول آن را ندارد [ضِمَارًا وَوَعْدًا].\nتأکید حضرت این است که مرگ را هرگز دور نپندارید. حضرت می‌فرمایند: گویی بار دوم در صور دمیده شده و شما وارد قیامت شده‌اید؛ قیامت آن‌قدر نزدیک است که گویی فرارسیده، اما ما آن را فراموش کرده‌ایم.\n🔷 «وَکذَلِک مَنْ عَظُمَتِ الدُّنْیا فِی عَینِهِ وَکبُرَ مَوْقِعُهَا مِنْ قَلْبِهِ»\nهمچنین کسی که دنیا در نگاهش بزرگ شود و جایگاه آن [مَوْقِعُهَا] در قلبش اهمیت فراوانی پیدا کند،\n🔷 «آثَرَهَا عَلَی اللَّهِ تَعَالَی»\nدنیا را بر خدا مقدم می‌دارد و آن را برمی‌گزیند [آثَرَ]؛ زیرا دنیا در نظرش بزرگ شده است.\nحضرت در جایی می‌فرمایند: درگذشته برادری داشتم که در چشم من بزرگ بود؛ زیرا دنیا در چشم او کوچک بود. مؤمنان واقعی دنیا را کوچک و حقیر می‌بینند. قرآن کریم می‌فرماید دنیا کالایی اندک است؛ اما این افراد، درحالی‌که ادعای رجا دارند، در برابر مردم کرنش می‌کنند. آنان کسانی هستند که دنیا را بزرگ می‌شمارند.\n🔷 «فَانْقَطَعَ إِلَیهَا وَصَارَ عَبْدًا لَهَا»\nبه دنیا دل می‌بندد و وابستگی کامل پیدا می‌کند.\nما از خداوند درخواست می‌کنیم:\n«إِلَهِی هَبْ لِی کمَالَ الْانْقِطَاعِ إِلَیک»\nخدایا، به ما عطا کن که گسستگی کامل از غیر تو و پیوند کامل با تو داشته باشیم.\nدر تاریخ، افرادی مانند عمر سعد نگرشی دنیاطلبانه داشتند و همه دغدغه‌شان دنیا بود؛ میان شهادت حسین بن علی علیه‌السلام و رسیدن به حکومت ری مردد ماندند و سرانجام حکومت ری را برگزیدند. از عمر سعد اشعاری نقل شده است که در این دوراهی می‌گفت:\nدنیا نقد و در دسترس است؛ کدام عاقل نقد را با نسیه معاوضه می‌کند؟ بهشت کجاست؟ وقتی غم دنیا بر انسان چیره شود، حسین علیه‌السلام را می‌کشد تا به دنیا برسد؛ اما مکتب پیامبر اکرم صلی‌الله علیه و آله می‌فرماید:\n«الدُّنْیا دَارُ مَنْ لَا دَارَ لَهُ»\nدنیا خانه کسی است که خانه‌ای ندارد.\n«وَلَهَا یجْمَعُ مَنْ لَا عَقْلَ لَهُ»\nکسی که عقل ندارد، برای دنیاگرد می‌آورد.\nاین دو مکتب را مقایسه کنید: نگرش دنیاطلبانه، حسین علیه‌السلام را می‌کشد تا به دنیا برسد؛ اما با نگاه رسول الهی، پیامبر اسوه زاهدان می‌شود.\n🔷 «وَلَقَدْ کانَ فِی رَسُولِ اللَّهِ صَلَّی اللَّهُ عَلَیهِ وَآلِهِ کافٍ لَک فِی الْأُسْوَةِ»\nمسلمان ناگزیر از پذیرفتن الگو و اسوه است. حتی رسول خدا صلی‌الله علیه و آله نیز اسوه دارد؛ جبرئیل علیه‌السلام اسوه اوست. پیامبر از طریق وحی با خداوند ارتباط دارد و به الگو و اسوه نیازمند است. پیامبر برای الگو بودن تو کافی است؛ پس باید نگاهت به او باشد.\n🔷 «وَدَلِیلٌ لَک عَلَی ذَمِّ الدُّنْیا وَعَیبِهَا»\nپیامبر برای همگان دلیل و راهنماست. اگر می‌خواهی دنیا را نکوهیده و معیوب ببینی، به پیامبر نگاه کن تا زشتی و مذمت دنیا در نگاهت آشکار شود.\nتفاوت اسوه و دلیل در این است که اسوه کسی است که باید به‌سوی او حرکت کنیم، اما دلیل کسی است که ما را به‌سوی خود راهنمایی می‌کند. پیامبر اسوه است و ما باید به‌سوی او برویم؛ پیامبر دلیل نیز هست، زیرا پیوسته ما را دعوت و راهنمایی می‌کند.\n🔷 «وَکثْرَةِ مَخَازِیهَا وَمَسَاوِیهَا»\nو ببینید که دنیا چه رسوایی‌های فراوانی [مَخَازِی] و چه بدی‌های بسیاری [مَسَاوِی] دارد.\n🔷 «إِذْ قُبِضَتْ عَنْهُ أَطْرَافُهَا، وَوُطِّئَتْ لِغَیرِهِ أَکنَافُهَا»\nببینید که چگونه دامنه‌های دنیا از پیامبر گرفته شد و اطراف‌واکناف آن برای دیگران هموار گردید. سفره دنیا از برابر پیامبر جمع شد و دنیا برای غیر او رام و آماده گردید [وُطِّئَتْ]؛ زیرا خداوند پیامبر را دوست داشت و دنیا را از پیشروی او برداشت.\n🔷 «وَفُطِمَ عَنْ رَضَاعِهَا، وَزُوِی عَنْ زَخَارِفِهَا»\nپیامبر از شیر دنیا گرفته شد [فُطِمَ] و از زر و زیورهای آن [زَخَارِف] دورنگه داشته شد.\nدنیا برای گروهی همچون مادری است که به آنان شیر می‌دهد و مایه رشد جسمی و روحی‌شان می‌شود؛ اما برای پیامبر، تمام زر و زیورهای دنیا کنار زده شد.\n🔷 «وَإِنْ شِئْتَ ثَنَّیتُ بِمُوسَی کلِیمِ اللَّهِ صَلَّی اللَّهُ عَلَیهِ»\nاگر بخواهید، نمونه دوم زهد و بی‌اعتنایی به دنیا را بیان می‌کنم: حضرت موسی کلیم‌الله علیه‌السلام.\n🔷 «حَیثُ یقُولُ: رَبِّ إِنِّی لِمَا أَنْزَلْتَ إِلَی مِنْ خَیرٍ فَقِیرٌ»\nآنجا که عرض کرد: پروردگارا، من به هر خیری که بر من فرو فرستی نیازمندم.\nحضرت موسی با طرف‌داران فرعون درگیر شد و با ضربه‌ای، فردی را کشت. سپس او را تعقیب کردند و موسی علیه‌السلام بدون آنکه خود را معرفی کند، از مصر گریخت. در مسیر، از گیاهان صحرایی تغذیه می‌کرد و از مصر به‌سوی شام رفت تا به مدین رسید. سپس ماجرای دختران شعیب پیش آمد. هنگامی که برای آنان آب کشید، گفت: خدایا، من فقیر و گرفتار تو هستم. زهد موسی در همین‌جا آشکار می‌شود.\n🔷 «وَاللَّهِ مَا سَأَلَهُ إِلَّا خُبْزًا یأْکلُهُ»\nبه خدا سوگند، هنگامی که موسی این درخواست را از خداوند کرد، تنها یک قرص نان [خُبْزًا] می‌خواست تا با آن یک وعده سیر شود. او باوجود همه رنج‌ها فقط یک وعده‌غذا درخواست کرد و این، جلوه‌ای از زهد موسی بود.\n🔷 «لِأَنَّهُ کانَ یأْکلُ بَقْلَةَ الْأَرْضِ»\nزیرا در این چند روز از گیاهان زمین تغذیه می‌کرد.\n🔷 «وَلَقَدْ کانَتْ خُضْرَةُ الْبَقْلِ تُرَی مِنْ شَفِیفِ صِفَاقِ بَطْنِهِ لِهَزَالِهِ وَتَشَذُّبِ لَحْمِهِ»\nآن‌قدر از گیاهان بیابانی خورده بود که سبزی گیاهان از زیر لایه‌های پوست شکمش [صِفَاقِ بَطْنِهِ] نمایان بود؛ زیرا به‌شدت لاغر [هَزَال] و گوشت بدنش تحلیل رفته و آب‌شده بود [تَشَذُّبِ لَحْمِهِ].\nهنگامی که موسی علیه‌السلام چنین گفت که من فقیرم، خداوند فرمود:\n«یا مُوسَی الْفَقِیرُ مَنْ لَیسَ لَهُ مِثْلِی کفِیلٌ»\nفقیر کسی است که کفیل و پشتیبانی مانند من نداشته باشد.\n🔷 «وَإِنْ شِئْتَ ثَلَّثْتُ بِدَاوُدَ صَلَّی اللَّهُ عَلَیهِ صَاحِبِ الْمَزَامِیرِ وَقَارِئِ أَهْلِ الْجَنَّةِ»\nاگر بخواهید، نمونه سوم را از حضرت داوود علیه‌السلام، صاحب مزامیر و قاری اهل بهشت، بیان می‌کنم.\nسومین نمونه، حضرت داوود نبی، صاحب مزامیر (کتاب دعای داوود) است. در روایات آمده است که هرگاه داوود مزامیر را می‌خواند، همه پرندگان و موجودات گرد او جمع می‌شدند. در بهشت نیز او مداح اهل بهشت است؛ بنابراین روشن است که صدایی زیبا داشته است. اما زهد او در چه چیزی بود؟\n🔷 «فَلَقَدْ کانَ یعْمَلُ سَفَائِفَ الْخُوصِ بِیدِهِ»\nحضرت داوود با دست خود زنبیل‌هایی می‌بافت و کارش همین بود. قرآن کریم درباره او می‌فرماید:\n«وَشَدَدْنَا مُلْکهُ وَآتَینَاهُ الْحِکمَةَ وَفَصْلَ الْخِطَابِ» (ص: ۲۰)\nحضرت داوود حکومت داشت؛ اما پیش از حکومت نیز از راه بافتن حصیرها امرارمعاش می‌کرد. او برای خود چیزی نمی‌خواست، اما به خداوند عرض کرد که مردم از او درخواست‌هایی دارند و فقرا نیازهایی را با او در میان می‌گذارند.\n«وَأَلَنَّا لَهُ الْحَدِیدَ»\nآهن در دست او نرم و رام شد. حضرت زره می‌بافت و آن‌ها را می‌فروخت و درآمدش را به فقرا می‌داد.\n🔷 «وَیقُولُ لِجُلَسَائِهِ: أَیکمْ یکفِینِی بِبَیعِهَا؟»\nو هر بار که حصیری می‌بافت، به همنشینان خود می‌گفت: کدام‌یک از شما حاضر است این حصیرها را از جانب من بفروشد؟\nاین جمله دو معنا دارد:\nنخست اینکه حضرت داوود به کارآفرینی می‌پرداخت؛ هم حصیر می‌بافت و هم زره‌هایی را که می‌ساخت برای فروش به دیگران می‌سپرد. پیامبران نیز کارآفرینی می‌کردند.\nدوم اینکه حضرت داوود هرگز شخصاً به بازار نمی‌رفت؛ زیرا حاکم بود و مردم ممکن بود کالا را به دلیل جایگاه او باقیمت بیشتری بخرند و روز بعد، انتظاراتی در آنان شکل بگیرد. برای رفع شبهه بی‌عدالتی، این شیوه را برگزیده بود که دیگران را برای فروش بفرستد.\n🔷 «وَیأْکلُ قُرْصَ الشَّعِیرِ مِنْ ثَمَنِهَا»\nو از بهای فروش حصیر، یک قرص نان جو تهیه می‌کرد و از دسترنج خود می‌خورد.\n🔷 «وَإِنْ شِئْتَ قُلْتُ فِی عِیسَی بْنِ مَرْیمَ عَلَیهِ السَّلَامُ»\nاگر بخواهید، چهارمین نمونه را درباره عیسی بن مریم علیه‌السلام بیان می‌کنم.\n🔷 «فَلَقَدْ کانَ یتَوَسَّدُ الْحَجَرَ»\nعیسی بن مریم، سنگ را زیر سرخود می‌گذاشت [یتَوَسَّدُ].\n🔷 «وَیلْبَسُ الْخَشِنَ وَیأْکلُ الْجَشِبَ»\nجامه‌های زبر و خشن می‌پوشید و نان خشک می‌خورد.\nعبدالله بن عباس می‌گوید حضرت علی علیه‌السلام نانی با خود داشت که با دست به‌سختی شکسته می‌شد، چه رسد به دندان. حضرت علی علیه‌السلام نیز در قله زهد و پارسایی قرار داشت.\n🔷 «وَکانَ إِدَامُهُ الْجُوعَ وَسِرَاجُهُ بِاللَّیلِ الْقَمَرُ»\nخورش [إِدَامُهُ] حضرت عیسی گرسنگی بود. برخی گفته‌اند آن‌قدر دیر غذا می‌خورد که بسیار گرسنه می‌شد و هر غذایی که برای او می‌آوردند، بهترین غذا به شمار می‌رفت.\nمعنای دوم این است که خورش و غذای لذیذ او گرسنگی بود؛ یعنی از گرسنگی لذت می‌برد و چراغ راهش در شب‌ها ماه بود.\n🔷 «وَظِلَالُهُ فِی الشِّتَاءِ مَشَارِقُ الْأَرْضِ وَمَغَارِبُهَا»\nپناهگاه او [ظِلَال] در زمستان، مشرق‌ها و مغرب‌های زمین بود؛ هنگام صبح رو به خورشید در مشرق می‌ایستاد و هنگام عصر به‌سوی مغرب و در برابر خورشید قرار می‌گرفت.\n🔷 «وَفَاکهَتُهُ وَرَیحَانُهُ مَا تُنْبِتُ الْأَرْضُ لِلْبَهَائِمِ»\nمیوه و سبزی او چیزهایی بود که زمین برای چهارپایان می‌رویاند.\n🔷 «وَلَمْ تَکنْ لَهُ زَوْجَةٌ تَفْتِنُهُ، وَلَا وَلَدٌ یحْزُنُهُ»\nهمسری نداشت که او را بفریبد [تَفْتِنُهُ] و به خود مشغول سازد، و فرزندی نداشت که او را اندوهگین کند.\n🔷 «وَلَا مَالٌ یلْفِتُهُ، وَلَا طَمَعٌ یذِلُّهُ»\nمالی نداشت که توجه او را به خود جلب کند [یلْفِتُهُ] و طمعی نداشت که او را به خواری بکشاند.\nداشتنی‌ها با رنج همراه‌اند؛ بنابراین اگر چیزی ندارید، اندوهگین نشوید. عیسی علیه‌السلام به مرتبه‌ای از زهد رسیده بود که هیچ طمعی در دل نداشت.\n🔷 «دَابَّتُهُ رِجْلَاهُ، وَخَادِمُهُ یدَاهُ»\nمرکب او پاهایش [دَابَّتُهُ] و خدمتگزار او دست‌هایش بودند؛ همه کارهایش را خود انجام می‌داد.\nحضرت علی علیه‌السلام فرمودند:\n«أَشْرَفُ الْغِنَی تَرْک الْمُنَی»\nبرترین بی‌نیازی، ترک آرزوها و نیازهاست. عیسی علیه‌السلام به بالاترین مرتبه بی‌نیازی معنوی رسیده بود.\nگاهی انسان از نظر مالی ثروتمند، اما در حقیقت فقیر است. زهد، همراه با بی‌نیازی و غنای معنوی، ارزشمند است.\nپس خوف‌ورجا داشته باشید و سپس از دنیا روی بگردانید؛ زیرا برای این مسیر الگو و اسوه داریم.\n«اللَّهُمَّ اجْعَلْ عَوَاقِبَ أُمُورِنَا خَیرًا»","بخش سوم\nمتن:\nالرسول الأعظم (صلی الله علیه وآله):\nفَتَأَسَّ بِنَبِيِّكَ الْأَطْيَبِ الْأَطْهَرِ، فَإِنَّ فِيهِ أُسْوَةً لِمَنْ تَأَسَّى وَ عَزَاءً لِمَنْ تَعَزَّى، وَ أَحَبُّ الْعِبَادِ إِلَى اللَّهِ الْمُتَأَسِّي بِنَبِيِّهِ وَ الْمُقْتَصُّ لِأَثَرِهِ؛ قَضَمَ الدُّنْيَا قَضْماً وَ لَمْ يُعِرْهَا طَرْفاً، أَهْضَمُ أَهْلِ الدُّنْيَا كَشْحاً وَ أَخْمَصُهُمْ مِنَ الدُّنْيَا بَطْناً. عُرِضَتْ عَلَيْهِ الدُّنْيَا، فَأَبَى أَنْ يَقْبَلَهَا؛ وَ عَلِمَ أَنَّ اللَّهَ سُبْحَانَهُ أَبْغَضَ شَيْئاً فَأَبْغَضَهُ، وَ حَقَّرَ شَيْئاً فَحَقَّرَهُ، وَ صَغَّرَ شَيْئاً فَصَغَّرَهُ؛ وَ لَوْ لَمْ يَكُنْ فِينَا إِلَّا حُبُّنَا مَا أَبْغَضَ اللَّهُ وَ رَسُولُهُ، وَ تَعْظِيمُنَا مَا صَغَّرَ اللَّهُ وَ رَسُولُهُ، لَكَفَى بِهِ شِقَاقاً لِلَّهِ وَ مُحَادَّةً عَنْ أَمْرِ اللَّهِ.\nوَ لَقَدْ كَانَ (صلی الله علیه وآله) يَأْكُلُ عَلَى الْأَرْضِ وَ يَجْلِسُ جِلْسَةَ الْعَبْدِ وَ يَخْصِفُ بِيَدِهِ نَعْلَهُ وَ يَرْقَعُ بِيَدِهِ ثَوْبَهُ وَ يَرْكَبُ الْحِمَارَ الْعَارِيَ وَ يُرْدِفُ خَلْفَهُ. وَ يَكُونُ السِّتْرُ عَلَى بَابِ بَيْتِهِ فَتَكُونُ فِيهِ التَّصَاوِيرُ، فَيَقُولُ يَا فُلَانَةُ لِإِحْدَى أَزْوَاجِهِ غَيِّبِيهِ عَنِّي، فَإِنِّي إِذَا نَظَرْتُ إِلَيْهِ ذَكَرْتُ الدُّنْيَا وَ زَخَارِفَهَا. فَأَعْرَضَ عَنِ الدُّنْيَا بِقَلْبِهِ وَ أَمَاتَ ذِكْرَهَا مِنْ نَفْسِهِ، وَ أَحَبَّ أَنْ تَغِيبَ زِينَتُهَا عَنْ عَيْنِهِ، لِكَيْلَا يَتَّخِذَ مِنْهَا رِيَاشاً وَ لَا يَعْتَقِدَهَا قَرَاراً وَ لَا يَرْجُوَ فِيهَا مُقَاماً، فَأَخْرَجَهَا مِنَ النَّفْسِ وَ أَشْخَصَهَا عَنِ الْقَلْبِ وَ غَيَّبَهَا عَنِ الْبَصَرِ؛ وَ كَذَلِكَ مَنْ أَبْغَضَ شَيْئاً، أَبْغَضَ أَنْ يَنْظُرَ إِلَيْهِ وَ أَنْ يُذْكَرَ عِنْدَهُ.\nوَ لَقَدْ كَانَ فِي رَسُولِ اللَّهِ (صلی الله علیه وآله) مَا يَدُلُّكَ عَلَى مَسَاوِئِ الدُّنْيَا وَ عُيُوبِهَا، إِذْ جَاعَ فِيهَا مَعَ خَاصَّتِهِ وَ زُوِيَتْ عَنْهُ زَخَارِفُهَا مَعَ عَظِيمِ زُلْفَتِهِ. فَلْيَنْظُرْ نَاظِرٌ بِعَقْلِهِ أَكْرَمَ اللَّهُ مُحَمَّداً بِذَلِكَ أَمْ أَهَانَهُ؟ فَإِنْ قَالَ أَهَانَهُ فَقَدْ كَذَبَ وَ اللَّهِ الْعَظِيمِ بِالْإِفْكِ الْعَظِيمِ؛ وَ إِنْ قَالَ أَكْرَمَهُ فَلْيَعْلَمْ أَنَّ اللَّهَ قَدْ أَهَانَ غَيْرَهُ حَيْثُ بَسَطَ الدُّنْيَا لَهُ، وَ زَوَاهَا عَنْ أَقْرَبِ النَّاسِ مِنْهُ. فَتَأَسَّى مُتَأَسٍّ بِنَبِيِّهِ وَ اقْتَصَّ أَثَرَهُ وَ وَلَجَ مَوْلِجَهُ وَ إِلَّا فَلَا يَأْمَنِ الْهَلَكَةَ، فَإِنَّ اللَّهَ جَعَلَ مُحَمَّداً (صلی الله علیه وآله) عَلَماً لِلسَّاعَةِ وَ مُبَشِّراً بِالْجَنَّةِ وَ مُنْذِراً بِالْعُقُوبَةِ، خَرَجَ مِنَ الدُّنْيَا خَمِيصاً وَ وَرَدَ الْآخِرَةَ سَلِيماً. لَمْ يَضَعْ حَجَراً عَلَى حَجَرٍ حَتَّى مَضَى لِسَبِيلِهِ وَ أَجَابَ دَاعِيَ رَبِّهِ. فَمَا أَعْظَمَ مِنَّةَ اللَّهِ عِنْدَنَا حِينَ أَنْعَمَ عَلَيْنَا بِهِ سَلَفاً نَتَّبِعُهُ وَ قَائِداً نَطَأُ عَقِبَهُ. وَ اللَّهِ لَقَدْ رَقَّعْتُ مِدْرَعَتِي هَذِهِ حَتَّى اسْتَحْيَيْتُ مِنْ رَاقِعِهَا، وَ لَقَدْ قَالَ لِي قَائِلٌ أَلَا تَنْبِذُهَا عَنْكَ؟ فَقُلْتُ [اعْزُبْ] اغْرُبْ عَنِّي، فَعِنْدَ الصَّبَاحِ يَحْمَدُ الْقَوْمُ السُّرَى.\nترجمه:\n(تو اى مسلمان)، به پيامبر پاک و پاکيزه ات(صلى الله عليه وآله) تأسّى جوى; زيرا در او سرمشقى است براى آن کس که مى خواهد تأسّى جويد و رابطه اى است عالى براى کسى که بخواهد به او مربوط شود، محبوب ترين بندگان نزد خدا کسى است که به پيامبرش تأسّى جويد و در پى او گام بردارد. او به اندازه نياز از دنيا بهره گرفت و هرگز تمايلى به آن نشان نداد. اندامش از همه مردم لاغرتر و شکمش از همه گرسنه تر بود. دنيا (از سوى خدا) به وى عرضه شد، ولى آن را نپذيرفت. او مى دانست چه چيزى مبغوض خداست؟ آن را مبغوض مى شمرد، چه چيز نزد خدا حقير است آن را حقير مى دانست و چه چيز نزد او کوچک است آن را کوچک مى ديد.\nو اگر در ما چيزى جز محبّت به آن چه مورد خشم خدا و رسولش مى باشد، و نيز بزرگ شمردن آن چه خدا و رسولش آن را کوچک شمرده اند وجود نداشته باشد، همين امر براى مخالفت ما با خدا و سرپيچى از فرمانش کافى است.\nپيامبر(صلى الله عليه وآله) روى زمين (بدون فرش) مى نشست و غذا مى خورد و با تواضع، همچون بردگان جلوس داشت، با دست خود پارگى کشف خويش را مى دوخت و با دست خود لباسش را وصله مى زد. بر مرکب برهنه سوار مى شد و (حتى) کسى را پشت سر خود سوار مى کرد. پرده اى بر در اتاق خود ديد که در آن تصويرهايى بود. همسرش را صدا زد و فرمود: آن را از نظرم پنهان کن که هر زمان چشمم به آن مى افتد به ياد دنيا و زر و زيور آن مى افتم.\nبه اين ترتيب با قلب خود (و تمام وجودش) از زر و زيور دنيا روى گردان بود و ياد آن را در وجود خود ميراند و دوست داشت زر و زيور آن همواره از چشمش پنهان باشد; مبادا از آن لباس فاخرى براى خود تهيه کند و دنيا را قرارگاه خويش پندارد و اميد اقامت در آن را داشته باشد; در نتيجه آن را از جان خود بيرون راند و از قلب خود دور ساخت و از ديدگانش پنهان نمود (آرى،) چنين است آن کسى که چيزى را مبغوض مى دارد و نگاه کردن و يادآورى آن را نيز مبغوض مى شمرد.\nدر زندگى رسول خدا(صلى الله عليه وآله) امورى است که تو را به بدى ها و عيوب دنيا راهنمايى مى کند; چرا که او و نزديکانش در دنيا گرسنه بودند، و يا اين که او (در پيشگاه خدا) مقام و منزلتى بس عظيم داشت، زينت هاى دنيا از او دريغ داشته شد; بنابراين هر کس بايد با عقل خودش بنگرد که آيا خدا با اين کار پيامبرش را گرامى داشت يا به او اهانت کرد؟ اگر کسى بگويد: خدا با اين کار (گرفتن زخارف دنيا از آن حضرت) به او اهانت نموده ـ سوگند به پروردگار متعال ـ که دروغ گفته است; دروغى بزرگ و اگر بگويد: او را گرامى داشته پس بايد بداند که ديگران را (که غرق زينت هاى دنيا هستند) گرامى نداشته است; چرا که دنيا را براى آن ها گسترده و از مقرّب ترين افراد به خودش دريغ داشته است;\nبنابراين (کسى که مى خواهد سعادتمند شود) بايد به پيامبر خود تأسى جويد، گام در جاى گام هايش نهد و از هر درى که او داخل شده وارد شود و الا از هلاکت (و گمراهى) ايمن نخواهد بود; زيرا خداوند، محمّد ـ که درود خدا بر او و خاندانش باد ـ را نشانه قيامت و بشارت دهنده بهشت و بيم دهنده کيفر قرار داده است. او با شکم گرسنه از اين جهان رحلت کرد و با سلامت (روح و ايمان) به سراى ديگر وارد شد. او تا آن زمان که از جهان رخت بر بست و دعوت حق را اجابت کرد سنگى روى سنگ ننهاد (و خانه محکمى براى خود نساخت) چه منّت بزرگى خدا بر ما نهاده که چنين پيشوا و رهبرى به ما عنايت کرده، تا راه او را بپوييم و قدم در جاى قدم هاى او نهيم. به خدا سوگند!\nآن قدر اين پيراهنم را وصله زدم که از وصله کننده آن شرم دارم (تا آن جا که) کسى به من گفت: چرا اين پيراهن کهنه را دور نمى افکنى؟ گفتم: از من دور شو. صبحگاهان، رهروان شب را ستايش مى کنند! (و فرداى قيامت وضع ما روشن مى شود).\nتفسیر:\nدر بخش‌های پیشین، پیرامون موضوعات گوناگون از جمله زهد و معرفی چهار پیامبر الهی به‌عنوان اسوه‌ها و مصادیق زهد سخن به میان آمد. این بخش به توجه دادن به سیره پیامبر اکرم (ص) و الگو قراردادن ایشان اختصاص دارد.\n«فَتَأَسَّ بِنَبِیک الْأَطْیبِ الْأَطْهَرِ صَلَّی اللَّهُ عَلَیهِ وَآلِهِ»\nتأسی بجویید از پیغمبر خاتم که وجود مقدس ایشان طیب‌وطاهر بود.\n«فَإِنَّ فِیهِ أُسْوَةً لِمَنْ تَأَسَّی، وَعَزَاءً لِمَنْ تَعَزَّی»\nاین وجود پاک برای هر کس که خواهان پیروی باشد، اسوه است؛ و اگر کسی طالب نباشد، برای او الگو نیست.\nسیره و روش پیامبر، عزت‌آفرین است؛ برای کسی که طالبِ عزت باشد [تَعَزَّی].\nمعنای دوم «تَعَزَّی»، منسوب بودن است؛ پیامبر بهترین هویت برای کسی است که این پیوند را بخواهد.\nطبق روایت: «أَنَا وَعَلِی أَبَوَا هَذِهِ الْأُمَّةِ» (من و علی پدران این امتیم)، به شرطی که شما این عزت‌مندی و انتساب را طلب کنید.\n«وَأَحَبُّ الْعِبَادِ إِلَی اللَّهِ الْمُتَأَسِّی بِنَبِیهِ، وَالْمُقْتَصُّ لِأَثَرِهِ»\nمحبوب‌ترین بنده در پیشگاه خداوند کسی است که از سیره پیامبرش پیروی کند و گام در جای پای او نهد.\nمحبوب‌ترین شخص، کسی است که دنباله‌رو [الْمُقْتَصُّ] آثار پیامبر باشد و معارف ایشان را دنبال کند.\nاین الگو دارای چنین ویژگی‌هایی است:\n«قَضَمَ الدُّنْیا قَضْماً، وَلَمْ یعِرْهَا طَرْفاً»\nاز دنیا به‌اندازه لقمه‌ای کوچک و خشک بهره برد [قَضْماً] (کنایه از حداقل بهره‌مندی) و اندک‌اندک از دنیا استفاده کرد؛ و حتی به‌اندازه یک‌گوشه چشم [طَرْفاً] به زرق‌وبرق دنیا نگاه نکرد و به آن دلبسته و وابسته نبود.\n«أَهْضَمُ أَهْلِ الدُّنْیا کشْحاً»\nپیامبر لاغرترین اهل دنیا بود؛ پهلوها [کشْحاً] و شکم مبارکش فربه نبود (و به دنیا بی‌رغبت و زاهد بود).\n«عُرِضَتْ عَلَیهِ الدُّنْیا فَأَبَی أَنْ یقْبَلَهَا، وَأَخْمَصُهُمْ مِنَ الدُّنْیا بَطْناً»\nدنیا به ایشان عرضه شد، اما از پذیرش آن سرباز زد؛ شکم ایشان [أَخْمَصُهُمْ] تهی‌ترین نسبت به جلوه‌های دنیا بود. با اینکه امکان برخورداری داشت، به دنیا روی نیاورد و زهد را پیشه خود ساخت.\nمیان نخوردن و ضعیف‌بودن، و میان پرخوری و نیرومندی تفاوت است و هیچ تناسبی میان آن‌ها نیست؛ انسان کم‌خوراک لزوماً ناتوان نیست و پرخور نیز قدرتمند شمرده نمی‌شود.\nفرمود: همانند درخت بیابانی که تنها از آب باران سیراب می‌شود و چوبی محکم‌تر دارد، در مقایسه با درخت باغ و بوستان شهری که پیوسته آبیاری می‌شود.\nما کم می‌خوریم؛ اما مستحکم و با استقامت هستیم؛ پرخوری نشانه سستی و وابستگی به خوراک است و با اندک تحریم و کمبودی، به‌سرعت فرد را از پای درمی‌آورد.\n«وَعَلِمَ أَنَّ اللَّهَ سُبْحَانَهُ أَبْغَضَ شَیئاً فَأَبْغَضَهُ»\nپیامبر می‌دانست آنچه نزد خداوند مبغوض است، باید مورد کراهت قرار گیرد، و آنچه نزد خدا محبوب است، دوست‌داشتنی است.\n«وَحَقَّرَ شَیئاً فَحَقَّرَهُ، وَصَغَّرَ شَیئاً فَصَغَّرَهُ»\nآنچه را در پیشگاه خداوند بی‌ارزش بود حقیر می‌شمرد، و آنچه را نزد پروردگار کوچک بود، خرد می‌دید.\nحرکت پیامبر در مدار رضای الهی جریان داشت و حرکت ما نیز باید در مدار سیره رسول خدا باشد.\nتفاوت «حقیر» و «صغیر»:\nحقیر: ناظر به کوچکی و پستی از حیث کیفیت است (مانند فرد نادان که شأن انسانی در او بی‌مقدار است).\nصغیر: ناظر به کوچکی از جهت کمیت است (مانند کودک خردسال که سن و اندازه کمی دارد).\n«وَلَوْ لَمْ یکنْ فِینَا إِلَّا حُبُّنَا مَا أَبْغَضَ اللَّهُ وَرَسُولُهُ، وَتَعْظِیمُنَا مَا صَغَّرَ اللَّهُ وَرَسُولُهُ»\nنباید در جان ما این صفت رخنه کند که آنچه را خدا و پیامبرش مبغوض شمرده‌اند دوست بداریم، و آنچه را خدا و پیامبرش کوچک دانسته‌اند، بزرگ و مهم انگاریم.\nحب و بغض ما باید بر مدار امام و ولی حق باشد؛ غایت آن، خشنودی قلبی آل الله و پیشوای جامعه قرار گیرد.\n«لَکفَی بِهِ شِقَاقاً لِلَّهِ، وَمُحَادَّةً عَنْ أَمْرِ اللَّهِ»\nهمین یک انحراف در دوستی‌ها و دشمنی‌ها برای سرکشی و مخالفت آشکار با فرمان خداوند بس است.\nهر کس که پیرو راستین امام است، باید سه ویژگی بنیادین داشته باشد:\n۱. درک کند که در قلب امام، دوستی و بیزاری به چه اموری تعلق‌گرفته است.\n۲. به آنچه محبوب امام است عمل کند و از آنچه موجب ناخشنودی اوست بپرهیزد.\n۳. هنگامی که گرایش و رضایت امام را به موضوعی که هنوز آشکارا بیان نشده دریافت و به آن عملکرد، در برابر سرزنش‌ها و طعنه‌های دیگران پایداری ورزد.\n«وَلَا یخَافُونَ لَوْمَةَ لَائِمٍ» (مائده: ۵۴)؛ از سرزنش هیچ ملامتگری نمی‌ترسند.\nحب و بغض ما باید با خواست خدا و پیامبر هماهنگ باشد؛ محبت نباید هدر رود، بلکه باید طبق موازین الهی سامان یابد و در مسیر خاندان رسالت هدایت شود. حرکت پیامبر در مدار خواست خدا بود و مسیر ما نیز باید در مدار رهنمودهای رسول خدا قرار گیرد.\nپیامبر اکرم (ص) همواره چنین سیره ارجمندی داشتند:\n«وَلَقَدْ کانَ صَلَّی اللَّهُ عَلَیهِ وَآلِهِ یأْکلُ عَلَی الْأَرْضِ، وَیجْلِسُ جِلْسَةَ الْعَبْدِ»\nهنگام تناول طعام، بر روی زمین و بدون گستردن فرش می‌نشست و غذا میل می‌فرمود؛ و کیفیت نشستن ایشان همانند بندگان و با نهایت ادب و خضوع، به‌صورت دوزانو بود.\n«وَیخْصِفُ بِیدِهِ نَعْلَهُ، وَیرْقَعُ بِیدِهِ ثَوْبَهُ»\nبا دستان مبارک خود پای‌افزارش را پینه‌دوزی می‌کرد و بر جامه خویش وصله می‌زد.\n«وَیرْکبُ الْحِمَارَ الْعَارِی، وَیرْدِفُ خَلْفَهُ»\nبر مرکب بی‌زین و پالان [الْعَارِی] سوار می‌شد (بدون تجمل و تکلف، در اوج فروتنی)؛ و اگر کسی پیاده بود، او را پشت سر خویش [یرْدِفُ] سوار می‌کرد.\n«وَیکونُ السِّتْرُ عَلَی بَابِ بَیتِهِ فَتَکونُ فِیهِ التَّصَاوِیرُ»\nپرده‌ای از نگاره‌های ذی‌روح بر درِ خانه آویخته بود.\n«فَیقُولُ: یا فُلَانَةُ - لِإِحْدَی أَزْوَاجِهِ - غَیبِیهِ عَنِّی»\nبه یکی از همسران خود فرمود: این پرده را از پیش چشمم بردار؛ زیرا دنیا و جلوه‌های آن را به یادم می‌آورد؛ آن را از من دور کن [غَیبِیهِ].\n(هر آنچه نشانی از جلوه‌های فریبنده دنیا دارد، از برابر دیدگان برکنار دارید.)\n«فَإِنِّی إِذَا نَظَرْتُ إِلَیهِ ذَکرْتُ الدُّنْیا وَزَخَارِفَهَا»\nزیرا هنگامی که چشمم به آن می‌افتد، به یاد دنیا و زرق و برق‌های آن می‌افتم؛ ازاین‌رو، هر آنچه دنیا و تجملاتش را یادآوری کند، از خود دور می‌سازم.\nنکته:\nپندار غلطی در میان برخی افراد جامعه وجود دارد که گمان می‌کنند هنر مؤمن زیستن در بستر فساد و آلودگی و حفظ ایمان است؛ اما حضرت فرمود باید تا جای ممکن از زمینه‌ها و عوامل گناه فاصله گرفت، و ایمان را چنان تقویت نمود که اگر انسان ناخواسته در موقعیت لغزش واقع شد، خود نگه‌دار باشد؛ اما از آغاز نباید به مرزهای گناه نزدیک شد.\n«فَأَعْرَضَ عَنِ الدُّنْیا بِقَلْبِهِ، وَأَمَاتَ ذِکرَهَا مِنْ نَفْسِهِ»\nپیامبر با تمام وجود از دنیا روی گرداند و یاد و رغبت به آن را در جان خویش خاموش ساخت.\n«وَأَحَبَّ أَنْ تَغِیبَ زِینَتُهَا عَنْ عَینِهِ، لِکیلَا یتَّخِذَ مِنْهَا رِیاشاً»\nدوست می‌داشت که زرق‌وبرق دنیا از برابر دیدگانش پنهان باشد، تا مبادا از تجملات و جلوه‌های آن، لباس فاخر و زینتی برگزیند.\n«وَلَا یعْتَقِدَهَا قَرَاراً، وَلَا یرْجُوَ فِیهَا مُقَاماً»\nتا نه دنیا را جایگاه آرامش و قرار شمارد و نه در آن امید اقامت و ماندگاری بندد.\n(پیرایه‌های مادی را دور سازید و به اندک بسنده کنید تا دل وابسته نگردد و روان به آرامش دست یابد.)\nپیامبری که دارای عصمت مطلق است، با این‌همه همواره مراقب و مهارکننده نفس خویش بود؛ چرا که مقام عصمت مانع از پرهیز و تلاش اختیاری نیست؛ بنده باید بااراده خود راه دوری از گناه را بپیماید تا عنایت و طهارت الهی افزون‌تر گردد.\n«فَأَخْرَجَهَا مِنَ النَّفْسِ، وَأَشْخَصَهَا عَنِ الْقَلْبِ، وَغَیبَهَا عَنِ الْبَصَرِ»\nدنیا را از جان خویش بیرون راند، آن را از حریم دل کوچاند [أَشْخَصَهَا]، و از پیش دیدگان خود پنهان ساخت.\n«وَکذَلِک مَنْ أَبْغَضَ شَیئاً أَبْغَضَ أَنْ ینْظُرَ إِلَیهِ، وَأَنْ یذْکرَ عِنْدَهُ»\nو چنین است که هر کس از چیزی بیزار باشد، از تماشای آن اکراه دارد و یادآوری نام‌ونشان آن نزد وی ناخوشایند است.\nاگر دنیا نزد شما ناپسند باشد، نگریستن به آن همراه با لذت نخواهد بود؛ چه آنکه ظاهر دنیا نرم و فریبنده است، اما باطنش زهری هلاکت بار است؛ پس اگر چشمی شیفته دنیا شد، باید دانست که دل نیز هنوز در بند تعلقات آن گرفتار است.\n«وَلَقَدْ کانَ فِی رَسُولِ اللَّهِ مَا یدُلُّک عَلَی مَسَاوِی الدُّنْیا وَعُیوبِهَا»\nدر سیره رسول خدا (ص) نشانه‌های روشنی است که بدی‌ها [مَسَاوِی] و عیب‌های دنیا را به تو بازمی‌نمایاند؛ توجه به مشی ایشان، راهنمایی بزرگ در شناخت کاستی‌های دنیاست.\n«إِذْ جَاعَ فِیهَا مَعَ خَاصَّتِهِ»\nبا تمام شوکت و عظمتی که داشت، در این سرا همراه با نزدیکان و اهل‌بیت خویش طعم گرسنگی [جَاعَ] را چشید.\n«وَزُوِیتْ عَنْهُ زَخَارِفُهَا مَعَ عَظِیمِ زُلْفَتِهِ»\nباوجود قرب و منزلتی بس بلند نزد پروردگار [زُلْفَتِهِ]، تجملات و زر و زیورهای دنیا از ساحت ایشان دور نگاه‌داشته شد [زُوِیتْ]؛ چرا که اگر دنیا ارزشی حقیقی می‌داشت، پروردگار آن را نصیب فرستادگان برگزیده‌اش می‌فرمود.\nما نباید در برابر انجام تکالیف و عباداتی ناچیز، خود را از خداوند طلبکار بدانیم و انتظار ریزش مداوم نعمت‌های دنیوی را داشته باشیم؛ درحالی‌که اشرف مخلوقات و سرآمد آفرینش، باکمال زهد و در عین تنگدستی مادی زیست.\nاز حضرت یوسف (ع) پرسیدند: با آنکه تمام گنجینه‌ها و خزاین زمین در اختیار توست، چرا گرسنگی را برمی‌گزینی؟\nفرمود:\nتا رنج بینوایان را دریابم؛\nبا پرخوری، خرد به خواب رخوت می‌رود؛\nبا شکم انباشته، بالندگی حکمت آسیب می‌بیند؛\nسنگینی سیری، توفیق بندگی را می‌کاهد؛\nگرسنگی و کم‌خوری استعدادهای درون را شکوفا می‌سازد؛\nسرچشمه علم و کمال در بریدن از رفاه و زیستن در غربت است؛\nبه بیان غررالحکم: پرخوری و گوارایی سلامت در یک جا گرد نمی‌آیند.\n«فَلْینْظُرْ نَاظِرٌ بِعَقْلِهِ: أَکرَمَ اللَّهُ مُحَمَّداً بِذَلِک أَمْ أَهَانَهُ؟»\nپس هر صاحب‌خردی باید با دیده عقل بنگرد که آیا خداوند با این تقدیر ساده و زاهدانه پیامبر را گرامی داشته، یا او را بی‌مقدار شمرده است؟\n«فَإِنْ قَالَ: أَهَانَهُ، فَقَدْ کذَبَ وَاللَّهِ الْعَظِیمِ وَأَتَی بِالْإِفْک الْعَظِیمِ»\nاگر کسی بگوید خداوند او را خوار شمرده، به خدای بزرگ سوگند که دروغی محض گفته و به افترایی بس سهمگین دست‌زده است.\n«وَإِنْ قَالَ: أَکرَمَهُ، فَلْیعْلَمْ أَنَّ اللَّهَ قَدْ أَهَانَ غَیرَهُ حَیثُ بَسَطَ الدُّنْیا لَهُ»\nو اگر معترف شود که خداوند او را اکرام فرموده، پس باید بداند خداوند دیگرانی را که دامنه دنیا را برایشان گسترد، بی‌مقدار ساخته است؛\n«وَزَوَاهَا عَنْ أَقْرَبِ النَّاسِ مِنْهُ»\nو متاع دنیا را از مقرب‌ترین و شایسته‌ترین بندگان درگاه خویش دور داشته است [زَوَاهَا].\n«فَتَأَسَّی مُتَأَسٍّ بِنَبِیهِ، وَاقْتَصَّ أَثَرَهُ»\nپس هر رهرویی باید به پیامبر خویش اقتدا کند و گام در جای پای او نهد [اقْتَصَّ].\n«وَوَلَجَ مَوْلِجَهُ»\nو از همان مسیری که او گام نهاده وارد گردد؛\n«وَإِلَّا فَلَا یأْمَنِ الْهَلَکةَ»\nوگرنه اگر کسی طریق پیامبر را پی نگیرد و عبرت نیاموزد، از هلاکت در امان نخواهد بود.\n«فَإِنَّ اللَّهَ جَعَلَ مُحَمَّداً صَلَّی اللَّهُ عَلَیهِ وَآلِهِ عَلَماً لِلسَّاعَةِ، وَمُبَشِّراً بِالْجَنَّةِ، وَمُنْذِراً بِالْعُقُوبَةِ»\nهمانا خداوند حضرت محمد (ص) را نشانه و رایت قیامت، بشارت‌دهنده به پاداش بهشت و بیم‌دهنده از کیفر دوزخ قرار داده است.\n«لَمْ یضَعْ حَجَراً عَلَی حَجَرٍ حَتَّی مَضَی لِسَبِیلِهِ، وَأَجَابَ دَاعِی رَبِّهِ»\nهرگز در پی ساخت کاخ‌های مجلل برنیامد؛ این شیوه استوار ادامه داشت تا آنکه فرمان رحلت رسید و ندای حق را لبیک گفت.\n«خَرَجَ مِنَ الدُّنْیا خَمِیصاً، وَوَرَدَ الْآخِرَةَ سَلِیماً»\nبا شکمی تهی از زخارف دنیوی از این جهان رخت بر بست و با کوله‌باری از سلامت و پاکی کامل به سرای آخرت درآمد.\n«فَمَا أَعْظَمَ مِنَّةَ اللَّهِ عِنْدَنَا حِینَ أَنْعَمَ عَلَینَا»\nوه که چه منت و عطای بزرگی از سوی خداوند بر ما ارزانی شد، آنگاه که بر ما نعمت بخشید؛ وجود پیامبر موهبتی بی‌بدیل بود که با بعثت او راه زهد، هدایت و کمال فراروی ما گشوده گشت؛\n«بِهِ سَلَفاً نَتَّبِعُهُ»\nپیشوایی پیشین که باید در مسیر او گام برداریم؛\n«وَقَائِداً نَطَأُ عَقِبَهُ»\nو راهبری که پا جای پای او می‌گذاریم.\nو این حقیقتاً موهبت سترگی است که پروردگار بر ما روا داشته است.\nامیرالمؤمنین (ع) پس از ذکر فضایل پیامبر، به ترسیم جلوه‌ای از زهد و ساده‌زیستی خویش به‌عنوان آیینه همان اسوه کامل پرداختند:\n«وَاللَّهِ لَقَدْ رَقَّعْتُ مِدْرَعَتِی هَذِهِ حَتَّی اسْتَحْییتُ مِنْ رَاقِعِهَا»\nبه خدا سوگند آن‌قدر بر این ردای پشمین خود [مِدْرَعَتِی] وصله زدم که از دوزنده و وصله‌کننده آن [رَاقِعِهَا] شرمسار شدم.\n«وَلَقَدْ قَالَ لِی قَائِلٌ: أَلَا تَنْبِذُهَا عَنْک؟ فَقُلْتُ: اغْرُبْ عَنِّی»\nتا آنکه گوینده‌ای به من گفت: آیا این جامه کهنه را دور نمی‌افکنی؟ بدو گفتم: از من دور شو [اغْرُبْ].\n«فَعِنْدَ الصَّبَاحِ یحْمَدُ الْقَوْمُ السُّرَی»\n(ضرب‌المثل معروف عربی): در سپیده‌دمان بامداد، شب‌زنده‌داران و کاروانیانی که سختی پیمودن راه در تاریکی شب [السُّرَی] را به جان خریده‌اند، ستایش می‌شوند.\nفرمودند: با رخت‌بربستن از این دنیای فانی، همه جلوه‌ها و آسایش‌های زودگذر پایان می‌پذیرد؛ اما فردای قیامت، حقیقت این شکیبایی، شکوه معنوی و جایگاه والای ما بر همگان آشکار خواهد گشت.\n«اللَّهُمَّ ارْزُقْنَا التَّجَافِی عَنْ دَارِ الْغُرُورِ»"]});
